window.AelitaCrmWorkbench=function(host,{api,mutate,actor,openRecord,refreshLookups,openSegment,resumeJob,draftState={},onDraft}){
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const workStatus=k=>({uploading:'Источник загружается',ready:'Предпросмотр готов',prepared:'Ожидает проверки',running:'Ожидает продолжения / обрабатывается здесь',paused:'Приостановлено',done:'Завершено',cancelled:'Остановлено',stale:'Источники изменились',failed:'Ошибка'})[k]||'Нужна проверка';
 const rid=()=>crypto.randomUUID().replace(/-/g,'');
 const status=text=>{const el=host.querySelector('[data-status]');if(el)el.textContent=text;};
 const active=()=>host.isConnected&&window.AelitaStaffSession?.read()?.user?.id===actor;
 let workPermissions={prepareImport:true,applyImport:true,qualityReview:true,mergeRecords:true};
 let sourceItems=[],sourceResult=null,reviewRecord=null,reviewLookups=null;
 let importStep=1,savedSource=draftState.savedSource||'',savedFile=draftState.savedFile||null;
 let choiceQueue=Promise.resolve(),choiceError=null,plan=null,reviewFilter=draftState.reviewFilter||'all',sourceDraft=draftState.sourceDraft||'';
 let source=draftState.source||null,items=[],job=draftState.job||null,offset=draftState.offset||0,next=null,stopped=false,mode='import',scanOffset=0,scanRevision=null,pairs=[],issues=[],limitedScan=false,groupFilter='',issueFilter='',pairPage=0,issuePage=0,busy=false;
 const userKey='aelita-workbench-v814:'+actor;
 const memory={get:key=>{try{return JSON.parse(localStorage.getItem(userKey+':'+key));}catch{return null;}},set:(key,value)=>{try{localStorage.setItem(userKey+':'+key,JSON.stringify(value));}catch{}}};
 const labels={name:'Организация',city:'Город',website:'Сайт',emails:'Общая почта',phones:'Общие телефоны',person:'Контактное лицо',personEmails:'Почта человека',personPhones:'Телефон человека',position:'Должность',notes:'Примечания',type:'Тип'};
 host.innerHTML='<div class="row between"><h1>Порядок в базе</h1></div><nav class="wb-tabs" aria-label="Обработка базы"><button data-mode="import" aria-pressed="true">Загрузить организации</button><button data-mode="quality">Дубли и ошибки</button><button data-mode="history">История изменений</button><button data-mode="jobs">Незавершённая работа</button><button data-mode="helper">Разобрать заметку / найти подборку</button></nav><p data-status role="status" aria-live="polite"></p><div data-body></div>';
 const body=host.querySelector('[data-body]');host.crmWorkbenchDirty=()=>active()&&((body.querySelector('[data-source]')?.value??sourceDraft)!==savedSource||!!source?.file&&source.file!==savedFile);host.crmWorkbenchBeforeLeave=async()=>{sourceDraft=body.querySelector('[data-source]')?.value??sourceDraft;stopped=true;await choiceQueue;if(choiceError){status(choiceError.message);return false;}onDraft?.({sourceDraft,source,job,offset,reviewFilter,savedSource,savedFile});return true;};
 function renderImport(){body.innerHTML='<ol class="wb-stepper"><li><button data-import-step="1" aria-current="step">1. Источник</button></li><li><button data-import-step="2">2. Что распознано</button></li><li><button data-import-step="3">3. Проверка</button></li><li><button data-import-step="4">4. Результат</button></li></ol><p data-capacity role="status"></p>'+ '<section class="panel" data-source-step><h2>Источник данных</h2><label>Вставьте текст<textarea class="ym-disable-keys" data-source rows="6" maxlength="500000" placeholder="Название организации, город, контакты…"></textarea></label><div class="actions"><button data-parse disabled>Разобрать текст</button><button data-ai disabled>Разобрать с ИИ</button><label class="wb-file">Загрузить файл<input type="file" data-file disabled accept=".csv,.tsv,.xlsx,.txt,.docx,.pdf"></label></div><details><summary>Форматы и условия загрузки</summary><p class="hint">ИИ получает только выбранный фрагмент текста. Результат проверяется до сохранения. Файлы разбираются на устройстве: CSV, TSV, XLSX, TXT, DOCX, PDF с текстом; до 15 МБ. Одна партия — до 5000 строк. Сканы без текста требуют OCR.</p></details><details><summary>Параметры файла</summary><label>Кодировка<select data-encoding><option value="utf-8">UTF-8</option><option value="windows-1251">Windows-1251</option></select></label><div data-sheets></div></details></section><div data-mapping></div><div data-review></div>';
  body.querySelector('[data-source]').value=sourceDraft;api({action:'wb_readiness'}).then(r=>{if(!active()||!body.querySelector('[data-capacity]'))return;workPermissions=r.permissions;body.querySelector('[data-capacity]').textContent=(r.capacity.accurate?'Свободно карточек: '+r.capacity.remaining+' из '+r.capacity.limit+'. Организации и люди занимают отдельные карточки.':'Общую ёмкость базы проверит сотрудник с полным доступом перед применением.')+(r.features.import?'':' Импорт выключен; введённые данные можно сохранить для последующего разбора.');body.querySelectorAll('[data-parse],[data-ai],[data-file]').forEach(x=>x.disabled=!r.features.import||!r.permissions.prepareImport);if(r.features.import&&r.permissions.prepareImport)aiCall({action:'ai_capabilities'}).then(c=>{if(active()&&body.querySelector('[data-ai]'))body.querySelector('[data-ai]').disabled=!c.configured;}).catch(e=>{const ai=body.querySelector('[data-ai]');if(ai){ai.disabled=true;ai.insertAdjacentHTML('afterend','<p class="hint">Помощник: '+esc(e.message)+'. Обычный разбор доступен.</p>');}});}).catch(e=>status(e.message));if(source?.kind==='table')mapping();const last=memory.get('import');if(last?.id)body.querySelector('[data-review]').innerHTML='<button data-resume>Продолжить последнюю загрузку</button>';
 }
 function setImportStep(n){if(!body.querySelector('.wb-stepper'))return;if(n===2&&!source){status('Сначала выберите источник. Для вставленного текста распознанные строки находятся на шаге3.');return;}if(n>=3&&!job){status('Сначала подготовьте предпросмотр источника.');return;}if(n===4&&!body.querySelector('[data-download-problems]')){run(report);return;}importStep=n;for(const button of body.querySelectorAll('[data-import-step]')){if(Number(button.dataset.importStep)===n)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');}body.querySelector('[data-source-step]').hidden=n!==1;body.querySelector('[data-mapping]').hidden=n!==2;body.querySelector('[data-review]').hidden=n<3;const section=body.querySelector('[data-review]>.panel');if(section)for(const el of section.children)el.hidden=n===4&&!el.matches('[data-plan]');}
 function mapping(){if(source?.kind!=='table')return;const map=source.mapping||window.AelitaOrganizationParser.mapping(source.rows[source.headerRow||0]||[]);body.querySelector('[data-mapping]').innerHTML='<section class="panel"><h2>Колонки файла</h2><label>Строка заголовков<input class="ym-disable-keys" data-header type="number" min="1" max="'+source.rows.length+'" value="'+((source.headerRow||0)+1)+'"></label><div class="form-grid">'+Object.entries(labels).map(([key,label])=>'<label>'+label+'<select data-map="'+key+'"><option value="-1">Не загружать</option>'+source.rows[source.headerRow||0].map((h,i)=>'<option value="'+i+'" '+(map[key]===i?'selected':'')+'>'+esc(h||'Колонка '+(i+1))+'</option>').join('')+'</select><small data-column-samples="'+key+'">'+esc(source.rows.slice((source.headerRow||0)+1,(source.headerRow||0)+4).map(row=>row[map[key]]||'—').join(' / '))+'</small></label>').join('')+'</div><label>Имя шаблона колонок<input class="ym-disable-keys" data-template-name maxlength="60" placeholder="Например, выгрузка партнёра"></label><div class="actions"><button data-template-save>Сохранить шаблон колонок</button><button data-template-load>Восстановить шаблон для этих заголовков</button></div><button data-map-apply>Подготовить предпросмотр</button></section>';}
 async function upload(rows){if(!rows.length)throw Error('Не найдено организаций. Проверьте разбиение текста или колонки.');if(rows.length>5000)throw Error('В партии больше 5000 строк. Разделите файл.');stopped=false;const request=rid(),sourceName=source?.name||'Вставленный текст';const sourceHash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(rows))))].map(x=>x.toString(16).padStart(2,'0')).join('');let result;const previous=memory.get('import');if(previous?.sourceHash===sourceHash){try{result=await api({action:'wb_import_page',id:previous.id});}catch{}}if(result?.job?.status==='ready'){job=(await api({action:'wb_import_finish',id:result.job.id,recheck:true})).job;offset=0;await review();return;}if(!result||result.job.sourceHash!==sourceHash||result.job.expected!==rows.length)result=await api({action:'wb_import_start',total:rows.length,sourceName,sourceHash,request_id:request});job=result.job;memory.set('import',{id:job.id,sourceHash});let part=0,cursor=0;
  while(cursor<rows.length){if(!active()||stopped)return;let batch=[],bytes=0;while(cursor<rows.length&&batch.length<100){const size=new TextEncoder().encode(JSON.stringify(rows[cursor])).length;if(size>90000)throw Error('Одна строка слишком велика. Сократите примечания.');if(batch.length&&bytes+size>90000)break;bytes+=size;batch.push(rows[cursor++]);}status('Загружаем '+cursor+' из '+rows.length+'…');await api({action:'wb_import_append',id:job.id,rows:batch,part,request_id:request+'_'+part});part++;}
  savedSource=sourceDraft;savedFile=source?.file||null;status('Проверяем контакты и совпадения…');job=(await api({action:'wb_import_finish',id:job.id})).job;offset=0;await review();
 }

 function editRow(index){const row=items.find(x=>x.index===index),el=body.querySelector('[data-import-row="'+index+'"] [data-row-editor]'),raw=row.raw||{};const keys=['name','city','website','emails','phones','person','position','personEmails','personPhones','notes'];el.innerHTML='<form><div class="form-grid">'+keys.map(key=>'<label>'+esc(labels[key])+(key==='notes'?'<textarea class="ym-disable-keys" name="'+key+'" maxlength="4000">'+esc(raw[key]||'')+'</textarea>':'<input class="ym-disable-keys" name="'+key+'" maxlength="2000" value="'+esc(Array.isArray(raw[key])?raw[key].join('; '):raw[key]||'')+'">')+'</label>').join('')+'</div><button>Проверить исправления</button></form>';el.querySelector('form').onsubmit=event=>{event.preventDefault();run(async()=>{const data=Object.fromEntries(new FormData(event.currentTarget));for(const key of ['emails','phones','personEmails','personPhones'])data[key]=String(data[key]||'').split(/[;\n]+/).map(x=>x.trim()).filter(Boolean);await api({action:'wb_import_edit',id:job.id,index,previewRevision:job.reviewVersion,data});await review();});};}

 async function preserveChoice(index,raw){const currentJob=job;choiceQueue=choiceQueue.then(async()=>{if(!active()||job.id!==currentJob.id)return;const r=await api({action:'wb_import_selection',id:job.id,previewRevision:job.reviewVersion,selectionVersion:job.selectionVersion||0,changes:[{index,...raw}],request_id:rid()});job=r.job;const item=items.find(x=>x.index===index);if(item)item.decision=raw.action==='remove'?null:{index,...raw};const n=body.querySelector('[data-selected-count]');if(n)n.textContent='Выбрано во всей партии: '+job.selected;choiceError=null;}).catch(e=>{choiceError=e;status('Выбор не сохранён: '+e.message);});await choiceQueue;}
 function readChoice(el){const index=Number(el.dataset.importRow),row=items.find(x=>x.index===index);if(!el.querySelector('[data-selected]').checked)return{action:'remove'};const value=el.querySelector('[data-decision]')?.value||'skip',match=row.matches?.find(x=>x.id===value),group=value.startsWith('group:')?Number(value.slice(6)):null;const sameTarget=match?row.decision?.id===match.id:group!==null?row.decision?.groupWith===group:row.decision?.action==='create'&&row.decision?.groupWith==null;return{...(sameTarget?row.decision||{}:{}),index,action:value==='skip'?'skip':match?'update':'create',...(match?{id:match.id,revision:match.revision}:{}),...(group!==null?{groupWith:group}:{}),...(!match&&group===null?{forceCreate:row.matches?.length>0}:{}),...(group===null?{groupWith:undefined}:{})};}
 async function review(){await choiceQueue;if(choiceError)throw choiceError;const r=await api({action:'wb_import_page',id:job.id,offset,filter:reviewFilter});if(!active())return;job=r.job;if(job.status!=='ready'){status('Загружено '+job.uploaded+' из '+job.expected+'. Выберите тот же источник, чтобы продолжить проверенную загрузку.');return;}next=r.next;items=r.items;const names={new:'Новые',match:'Совпадения',error:'Ошибки',duplicate:'Повторы в файле'},decisions={all:'Все строки',new:'Новые',match:'Совпадения',error:'Ошибки',duplicate:'Повторы',selected:'Выбранные',applied:'Применённые',skipped:'Пропущенные'};
 body.querySelector('[data-review]').innerHTML='<section class="panel"><h2>3. Проверка изменений</h2><div class="wb-counts">'+Object.entries(job.counts).map(([k,n])=>'<span>'+esc(names[k]||k)+' <strong>'+n+'</strong></span>').join('')+'</div><label>Показать<select data-review-filter>'+Object.entries(decisions).map(([k,l])=>'<option value="'+k+'" '+(reviewFilter===k?'selected':'')+'>'+l+'</option>').join('')+'</select></label><p data-selected-count>Выбрано во всей партии: '+job.selected+'</p><p class="hint">Заполненные поля сохраняются. Через «Точные изменения» можно выбрать замену поля, связать существующего человека и проверить группировку.</p><div class="wb-rows">'+items.map(x=>{const disabled=x.errors?.length||x.status==='duplicate'||x.applied,d=x.decision;return '<article class="wb-import-row" data-import-row="'+x.index+'"><label class="check"><input type="checkbox" data-selected '+(disabled?'disabled':'')+' '+(d?'checked':'')+'> Строка '+(x.index+1)+'</label><h3>'+esc(x.data?.name||x.raw?.name||'Проверьте название')+'</h3><p>'+esc([x.data?.city,...(x.data?.channels||[]).map(c=>c.value)].filter(Boolean).join(' · '))+'</p>'+(x.person?'<p>Контактное лицо: '+esc(x.person.name)+(x.person.position?' · '+esc(x.person.position):'')+'</p>':'')+'<p class="hint">'+esc(x.source)+'</p>'+(x.applied?'<p>Применено · <button data-open-org="'+x.applied+'">Открыть организацию</button></p>':x.errors?.length?'<p class="error">'+esc(x.errors.join('; '))+'</p>':x.status==='duplicate'?'<p>Повтор строки '+(x.duplicateOf+1)+'</p>':'<label>Действие<select data-decision><option value="skip">Пропустить</option><option value="create" '+(!x.matches.length?'selected':'')+'>Создать отдельную организацию</option>'+ (x.groupCandidate!=null?'<option value="group:'+x.groupCandidate+'">Организация из строки '+(x.groupCandidate+1)+' · добавить человека/контакты</option>':'')+x.matches.map(m=>'<option value="'+m.id+'">Дополнить: '+esc(m.name)+' · '+esc(m.reasons.join(', '))+(m.conflicts.length?' · '+esc(m.conflicts.join(', ')):'')+'</option>').join('')+'</select></label>')+'<div class="actions"><button type="button" data-edit-row="'+x.index+'" '+(x.applied?'disabled':'')+'>Исправить строку</button><button type="button" data-diff-row="'+x.index+'" '+(disabled?'disabled':'')+'>Точные изменения</button></div><div data-row-editor></div><div data-row-diff></div></article>';}).join('')+'</div><div class="actions"><button data-select-page>Выбрать доступные строки страницы</button><button data-select-kind>Выбрать все подходящие строки категории</button><button data-apply>Проверить и применить весь выбор</button><button data-prev '+(offset?'':'disabled')+'>Назад</button><span>Показано '+items.length+' из '+r.filteredTotal+'</span><button data-next '+(next===null?'disabled':'')+'>Дальше</button><button data-report>Итог / проблемные строки</button><button data-share-import>Передать партию владельцу</button></div><div data-plan></div><div data-operation></div></section>';
 for(const row of items){const select=body.querySelector('[data-import-row="'+row.index+'"] [data-decision]');if(select&&row.decision)select.value=row.decision.groupWith!=null?'group:'+row.decision.groupWith:row.decision.action==='update'?row.decision.id:row.decision.action;}status('Предпросмотр: '+job.total+' строк. Применено: '+job.applied+'.');setImportStep(3);
 }
 async function showDiff(index){await choiceQueue;const row=items.find(x=>x.index===index),el=body.querySelector('[data-import-row="'+index+'"]'),raw=readChoice(el);if(raw.action==='remove'){el.querySelector('[data-selected]').checked=true;raw.action=el.querySelector('[data-decision]')?.value==='skip'?'skip':row.matches.find(x=>x.id===el.querySelector('[data-decision]')?.value)?'update':'create';Object.assign(raw,readChoice(el));}if(raw.action==='skip'){status('Выберите создание или дополнение для сравнения полей.');return;}const r=await api({action:'wb_import_diff',id:job.id,choice:{index,...raw}}),area=el.querySelector('[data-row-diff]');area.innerHTML='<section class="wb-diff"><h4>Сейчас → источник → результат</h4>'+r.fields.map(f=>'<div class="wb-field-diff"><strong>'+esc(labels[f.key])+'</strong><p>Сейчас: '+esc(f.before||'—')+'</p><p>Из источника: '+esc(f.incoming||'—')+'</p><label>Решение<select data-diff-field="'+f.key+'"><option value="keep">Сохранить заполненное</option>'+(f.key==='notes'?'<option value="append">Добавить к заметкам</option>':'')+'<option value="source">Взять из источника</option></select></label><p>После применения: '+esc(f.after||'—')+'</p></div>').join('')+'<div><strong>Контакты после дополнения</strong><p>'+esc(r.channels.after.map(c=>c.value+(c.extension?' доб.'+c.extension:'')).join(' · ')||'Нет общих контактов')+'</p></div>'+(r.person?'<label>Контактное лицо<select data-person-mode><option value="create">Создать отдельного человека</option><option value="skip">Не переносить человека из этой строки</option>'+r.people.map(c=>'<option value="'+c.id+'">Связать и дополнить: '+esc(c.name)+' · '+esc(c.emails.join(', '))+'</option>').join('')+'</select></label>':'')+'<button data-diff-save>Сохранить решения по строке</button></section>';
 for(const select of area.querySelectorAll('[data-diff-field]'))select.value=raw.fields?.[select.dataset.diffField]||(select.dataset.diffField==='notes'?'append':'keep');if(area.querySelector('[data-person-mode]'))area.querySelector('[data-person-mode]').value=raw.personMode==='link'?raw.personId:raw.personMode||'create';area.querySelector('[data-diff-save]').onclick=()=>run(async()=>{const c={...raw,fields:Object.fromEntries([...area.querySelectorAll('[data-diff-field]')].map(e=>[e.dataset.diffField,e.value]))},person=area.querySelector('[data-person-mode]')?.value;if(person){const p=r.people.find(x=>x.id===person);Object.assign(c,p?{personMode:'link',personId:p.id,personRevision:p.revision}:{personMode:person});}await preserveChoice(index,c);await showDiff(index);});
 }
 async function selectCategory(){await choiceQueue;let cursor=0;do{const r=await api({action:'wb_import_page',id:job.id,offset:cursor,filter:reviewFilter});const changes=r.items.filter(x=>!x.applied&&!x.errors?.length&&x.status!=='duplicate').map(x=>x.decision||{index:x.index,action:x.matches.length?'skip':'create',...(x.groupCandidate!=null?{groupWith:x.groupCandidate}:{})});if(changes.length)job=(await api({action:'wb_import_selection',id:job.id,previewRevision:job.reviewVersion,selectionVersion:job.selectionVersion||0,changes,request_id:rid()})).job;cursor=r.next;status('Сохраняем выбор: '+job.selected+' строк');}while(cursor!==null&&active());await review();}
 async function apply(){await choiceQueue;if(choiceError)throw choiceError;const selected=(await api({action:'wb_import_selected',id:job.id})).items;if(!selected.length)throw Error('Выберите строки во всей партии.');plan=(await api({action:'wb_import_plan',id:job.id,previewRevision:job.reviewVersion,selectionVersion:job.selectionVersion||0,request_id:rid()})).plan;memory.set('plan',{id:plan.id});const c=plan.counts;if(!workPermissions.applyImport){status('План подготовлен. Применение недоступно по вашим правам; передайте партию владельцу.');await shareImport();return;}if(!await AelitaConfirmMail({title:'4. Проверка всего плана',facts:[['Выбрано строк',c.selected],['Создать организаций',c.created],['Дополнить организаций',c.updated],['Карточек людей',c.people],['Пропустить строк',c.skipped],['Всего карточек после применения',c.recordsAfter+' из 5000']],warnings:['План фиксирован. Применение идёт порциями по 50 строк, пока страница открыта. Пауза останавливает следующие порции; начатая может завершиться.','Доступны отмены выполненных порций с проверкой последующих изменений.'],check:'Я проверил выбранные строки, людей и изменения полей',label:'Применить утверждённый план'}))return;plan=(await api({action:'wb_plan_control',planId:plan.id,control:'confirm',confirm:true,approvalDigest:plan.approvalDigest})).plan;await runPlan();}
 function renderPlan(){const el=body.querySelector('[data-plan]');if(!el)return;el.innerHTML='<section class="panel"><h3>Применение: '+plan.progress.done+' из '+plan.progress.total+' порций</h3><p>'+esc(({running:'Выполняется при открытой странице',paused:'Приостановлено',done:'Готово',cancelled:'Остановлено',changed:'Результат изменён после отмены',prepared:'Ожидает подтверждения'})[plan.status]||plan.status)+'</p><div class="actions">'+(plan.status==='prepared'?'<button data-apply>Проверить и подтвердить план</button>':'')+(plan.status==='running'?'<button data-plan-run>Продолжить обработку здесь</button><button data-plan-pause>Пауза</button>':plan.status==='paused'?'<button data-plan-resume>Продолжить</button>':'')+'<button data-plan-close>'+(plan.status==='done'?'Вернуться к строкам':'Остановить оставшиеся порции')+'</button></div>'+plan.operations.map(id=>'<button data-undo="'+id+'">Отменить порцию</button>').join('')+'</section>';}
 async function runPlan(){stopped=false;renderPlan();while(active()&&!stopped&&plan.status==='running'){try{const old=plan.progress.done,r=await mutate('wb_plan_step',{planId:plan.id,step:old},plan.id+'_step_'+old);plan=r.plan;renderPlan();status('Применено '+plan.progress.rows+' строк из '+plan.counts.selected);}catch(e){const current=(await api({action:'wb_plan_status',planId:plan.id})).plan;if(current.progress.done>plan.progress.done){plan=current;continue;}plan=(await api({action:'wb_plan_control',planId:plan.id,control:'pause'})).plan;renderPlan();throw e;}}if(stopped&&plan.status==='running')plan=(await api({action:'wb_plan_control',planId:plan.id,control:'pause'})).plan;renderPlan();await refreshLookups();if(plan.status==='done')status('План завершён. Создано организаций: '+plan.counts.created+', дополнено: '+plan.counts.updated+', карточек людей: '+plan.counts.people+'.');}
 async function shareImport(){const staff=(await api({action:'staff_list'})).items.filter(x=>x.role==='owner'&&!x.disabled),area=body.querySelector('[data-plan]');area.innerHTML='<section class="panel"><h3>Передача подготовленной партии</h3><label>Владелец<select data-review-owner>'+staff.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select></label><p>Выбранный владелец получит доступ к источнику, строкам и вашим решениям. Применение требует его отдельной проверки.</p><button data-share-confirm>Передать доступ к партии</button></section>';area.querySelector('[data-share-confirm]').onclick=()=>run(async()=>{job=(await api({action:'wb_import_share',id:job.id,reviewerId:area.querySelector('[data-review-owner]').value})).job;status('Доступ к партии передан выбранному владельцу. Рассылка или изменение CRM не запускались.');});}

 async function report(){let all=[],cursor=0;do{const r=await api({action:'wb_import_report',id:job.id,offset:cursor});all.push(...r.items);cursor=r.next;}while(cursor!==null&&active());const area=body.querySelector('[data-plan]');const counts={};all.forEach(x=>counts[x.status]=(counts[x.status]||0)+1);area.innerHTML='<section class="panel"><h3>Результат партии</h3><p>'+Object.entries(counts).map(([k,n])=>esc(({applied:'Применено',error:'Ошибки',duplicate:'Повторы',new:'Не применено',match:'Совпадения',skipped:'Пропущено'})[k]||k)+': '+n).join(' · ')+'</p><button data-download-problems>Скачать проблемные / оставшиеся строки</button><div class="actions">'+all.filter(x=>x.organizationId).slice(0,100).map(x=>'<button data-open-org="'+x.organizationId+'">'+esc(x.name)+'</button>').join('')+'</div></section>';area.querySelector('[data-download-problems]').onclick=()=>{const columns=['name','city','website','emails','phones','person','personEmails','personPhones','position','notes','type'];const lines=[['Строка','Статус','Причина','Источник',...columns.map(k=>labels[k])],...all.filter(x=>x.status!=='applied').map(x=>[x.index+1,x.status,x.reason,x.source,...columns.map(k=>Array.isArray(x.raw?.[k])?x.raw[k].join('; '):x.raw?.[k]||'')])];const csv='\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[\s]*[=+@-]/,"'$&")+'"').join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Импорт-остаток.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);};setImportStep(4);}
 async function jobs(){const r=await api({action:'wb_jobs'});body.innerHTML='<section class="panel"><h2>Незавершённая работа</h2><p>Задания сохраняются до 30 дней. Расчёт и применение продолжаются при открытой странице.</p>'+r.items.map(x=>'<article><h3>'+esc(x.sourceName||'Применение импорта')+'</h3><p>'+esc(new Date(x.createdAt).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'}))+' · '+esc(workStatus(x.status))+' · '+(x.kind==='import'?x.uploaded+' из'+x.expected+' строк':x.progress.done+' из'+x.progress.total+' порций')+'</p><button data-job-open="'+x.id+'" data-job-kind="'+x.kind+'">Открыть / продолжить</button></article>').join('')+(!r.items.length?'<p>Незавершённых заданий нет. Начните с загрузки организаций.</p>':'')+'</section><section class="panel" data-segment-jobs><h2>Подборки зрителей</h2><p>Проверяем сохранённые расчёты…</p></section><section class="panel" data-ai-jobs><h2>Задания помощника</h2><p>Проверяем доступность…</p></section>';try{const saved=await api({action:'segment_jobs'});if(active()&&body.querySelector('[data-segment-jobs]'))body.querySelector('[data-segment-jobs]').innerHTML='<h2>Подборки зрителей</h2>'+saved.items.map(x=>'<article><h3>'+esc(x.segmentName)+'</h3><p>'+esc(workStatus(x.status))+' · '+x.progress.scanned+' из '+x.progress.total+'</p><button data-segment-job="'+x.id+'" data-segment-id="'+x.segmentId+'">Открыть расчёт</button></article>').join('')+(!saved.items.length?'<p>За последние сутки расчётов нет.</p>':'');}catch(e){if(body.querySelector('[data-segment-jobs]'))body.querySelector('[data-segment-jobs]').textContent=e.message;}try{const a=await aiCall({action:'ai_jobs'});if(!active())return;body.querySelector('[data-ai-jobs]').innerHTML='<h2>Задания помощника</h2>'+(a.jobs.length?a.jobs.map(x=>'<article><p>'+esc(({crm_review:'Разбор выбранных записей',organization_extract:'Разбор организаций'})[x.kind]||'Подсказка')+' · '+esc(({queued:'В очереди',running:'В работе',done:'Готово',error:'Ошибка',canceled:'Отменено'})[x.status]||x.status)+'</p><button data-ai-job="'+x.id+'">Открыть / продолжить</button></article>').join(''):'<p>Ваших заданий нет. Результаты хранятся до 15 минут.</p>');}catch(e){if(body.querySelector('[data-ai-jobs]'))body.querySelector('[data-ai-jobs]').textContent=e.message;}}

 function showOperation(id){const area=body.querySelector('[data-operation]');if(area)area.innerHTML='<p>Изменения сохранены. <button data-undo="'+id+'">Отменить эту операцию</button></p>';}
 function renderQuality(){body.innerHTML='<section class="panel"><h2>Проверка базы</h2><label>Что проверять<select data-quality-type><option value="organizations">Организации</option><option value="contacts">Контактные лица</option></select></label><label class="check"><input type="checkbox" data-include-resolved> Показать разобранные пары</label><p>Поиск совпадений и неполных карточек. Ничего не объединяется автоматически.</p><div class="actions"><button data-scan>Проверить базу</button><button data-scan-stop>Остановить проверку</button></div></section><div data-pairs></div><div data-issues></div><div data-compare></div>';}
 async function scan(){stopped=false;pairs=[];issues=[];limitedScan=false;pairPage=0;issuePage=0;scanOffset=0;scanRevision=null;groupFilter='';issueFilter='';do{if(!active()||stopped)return;const r=await api({action:'wb_scan',offset:scanOffset,type:body.querySelector('[data-quality-type]').value,includeResolved:body.querySelector('[data-include-resolved]').checked});if(scanRevision!==null&&scanRevision!==r.revision)throw Error('База изменилась во время проверки. Запустите её заново.');scanRevision=r.revision;limitedScan ||= r.limited;pairs.push(...r.pairs);issues.push(...r.issues);scanOffset=r.next;status('Проверено '+r.processed+' из '+r.total);renderScan();await new Promise(resolve=>setTimeout(resolve,0));}while(scanOffset!==null);status('Проверка завершена. Пар: '+pairs.length+', замечаний: '+issues.length+'.');}
 function renderScan(){const issuesOpen=body.querySelector('[data-issues] details')?.open;const components=[];for(const p of pairs){const a=components.find(g=>g.has(p.left)),b=components.find(g=>g.has(p.right));if(a&&b&&a!==b){for(const id of b)a.add(id);components.splice(components.indexOf(b),1);}else if(a||b){(a||b).add(p.left);(a||b).add(p.right);}else components.push(new Set([p.left,p.right]));}const visible=groupFilter?pairs.filter(p=>components.find(g=>g.has(groupFilter))?.has(p.left)):pairs;const filteredIssues=issueFilter?issues.filter(x=>x.kind===issueFilter):issues;body.querySelector('[data-pairs]').innerHTML='<section class="panel">'+(limitedScan?'<p class="hint">Есть слишком широкие группы совпадений. Показана выборка кандидатов; отсутствие пары не означает отсутствие дубля. Уточните общие названия и контакты и повторите проверку.</p>':'')+'<h2>Возможные дубли · '+visible.length+'</h2><div class="actions"><button data-group="">Все группы · '+components.length+'</button>'+components.filter(g=>g.size>2).map(g=>'<button data-group="'+[...g][0]+'">Группа · '+g.size+' карточек</button>').join('')+'</div>'+visible.slice(pairPage*50,pairPage*50+50).map((p,i)=>'<article class="wb-pair"><h3>'+esc(p.leftName)+' / '+esc(p.rightName)+'</h3><p>'+esc(p.reasons.join(' · '))+'</p>'+(p.decision?'<p class="hint">Решение: '+esc(({different:'Разные',later:'Отложено',review:'Нужна проверка'})[p.decision.decision]||p.decision.decision)+' · '+esc(p.decision.actorName)+' · '+esc(new Date(p.decision.at).toLocaleString('ru-RU'))+(p.decision.reason?' · '+esc(p.decision.reason):'')+'</p>':'')+(p.reopened?'<p class="hint">'+esc(p.reopenedReason)+'</p>':'')+(p.conflicts.length?'<p class="error">'+esc(p.conflicts.join(' · '))+'</p>':'')+'<div class="actions"><button data-compare="'+p.left+':'+p.right+'">Сравнить</button><button data-different="'+p.left+':'+p.right+'">'+(p.type==='contacts'?'Разные люди':'Разные организации')+'</button></div></article>').join('')+'<div class="actions"><button data-pair-page="'+(pairPage-1)+'" '+(pairPage?'':'disabled')+'>Назад</button><span>Страница '+(pairPage+1)+' из '+Math.max(1,Math.ceil(visible.length/50))+'</span><button data-pair-page="'+(pairPage+1)+'" '+((pairPage+1)*50<visible.length?'':'disabled')+'>Дальше</button></div>'+'</section>';body.querySelector('[data-issues]').innerHTML='<details class="panel" '+(issuesOpen?'open':'')+'><summary>Неполные данные и ошибки · '+issues.length+'</summary><label>Тип замечания<select data-issue-filter><option value="">Все</option>'+[...new Set(issues.map(x=>x.kind))].map(k=>'<option value="'+k+'" '+(issueFilter===k?'selected':'')+'>'+esc(({missing_city:'Без города',missing_contacts:'Без общих контактов',missing_type:'Не уточнён тип',shared_personal_contact:'Уточнить владельца адреса',invalid_contact:'Некорректный контакт',external_id:'Повтор публичной связи',missing_relation:'Потеряна связь'})[k]||k)+'</option>').join('')+'</select></label>'+filteredIssues.slice(issuePage*50,issuePage*50+50).map(x=>'<p><button class="name-link" data-open-org="'+x.id+'" data-record-type="'+(x.type||'organizations')+'">'+esc(x.name)+'</button> · '+esc(x.message)+'</p>').join('')+'<div class="actions"><button data-issue-page="'+(issuePage-1)+'" '+(issuePage?'':'disabled')+'>Назад</button><span>Страница '+(issuePage+1)+' из '+Math.max(1,Math.ceil(filteredIssues.length/50))+'</span><button data-issue-page="'+(issuePage+1)+'" '+((issuePage+1)*50<filteredIssues.length?'':'disabled')+'>Дальше</button></div></details>';}
 function pairControls(area,type,a,b,left,right){const panel=document.createElement('section');panel.className='panel';panel.innerHTML='<h3>Решение команды</h3><label>Причина / что уточнить<textarea class="ym-disable-keys" data-decision-reason maxlength="500" rows="2"></textarea></label><div class="actions">'+Object.entries({different:type==='contacts'?'Разные люди':'Разные организации',later:'Вернуться через 7 дней',review:'Нужна проверка',reset:'Пересмотреть прежнее решение'}).map(([key,label])=>'<button data-pair-decision="'+key+'">'+label+'</button>').join('')+'</div>';area.append(panel);for(const button of panel.querySelectorAll('button'))button.onclick=()=>run(async()=>{await api({action:'wb_quality_decide',type,left:a,right:b,leftRevision:left.revision,rightRevision:right.revision,decision:button.dataset.pairDecision,reason:panel.querySelector('textarea').value});status('Решение сохранено для команды. Обновите проверку, чтобы увидеть общую очередь.');});}
 async function compare(ids){const [a,b]=ids.split(':');if(a.startsWith('c_')){await comparePeople(a,b);return;}const left=(await api({action:'get',type:'organizations',id:a})).entity,right=(await api({action:'get',type:'organizations',id:b})).entity;const area=body.querySelector('[data-compare]');const impact=await api({action:'wb_merge_preview',keep:a,other:b});const fields=['name','city','website','type'];area.innerHTML='<section class="panel"><h2>Сравнение организаций</h2><button data-swap-main>Сделать вторую карточку главной</button><div class="wb-compare">'+[left,right].map((x,i)=>'<div><h3>'+esc(x.name)+'</h3><p>'+esc(x.city)+'</p><p>'+esc(x.website)+'</p>'+'<dl>'+window.AelitaOrgChannels.detail(x)+'</dl><p>'+esc(x.notes)+'</p><button data-open-org="'+x.id+'">Открыть карточку</button></div>').join('')+'</div><p>Главной останется первая карточка. Контакты и связи объединяются; прежняя карточка с заметками и письмами сохраняется в архиве.</p><details open><summary>Затрагиваемые связи · '+impact.records.length+'</summary>'+'<div data-impact-records>'+impact.records.slice(0,50).map(x=>'<p>'+esc(x.type)+' · <button data-open-org="'+x.id+'" data-record-type="'+x.type+'">'+esc(x.name)+'</button></p>').join('')+'</div>'+(impact.records.length>50?'<button data-impact-more>Показать следующие связи</button>':'')+'<p>Записей почты и черновиков: '+Object.values(impact.mail).reduce((a,b)=>a+b,0)+'. Они сохраняются по прежним карточкам.</p>'+impact.warnings.map(x=>'<p class="hint">'+esc(x)+'</p>').join('')+(impact.publicConflict?'<p class="error">Разные публичные страницы: объединение заблокировано.</p>':'')+'</details><div class="form-grid">'+fields.map(k=>'<label>'+esc(labels[k]||k)+'<select data-merge-field="'+k+'"><option value="keep">'+esc(left[k]||'—')+'</option><option value="other">'+esc(right[k]||'—')+'</option></select></label>').join('')+'</div><button data-merge>Объединить с проверкой ревизий</button><div data-operation></div></section>';let impactOffset=50;const more=area.querySelector('[data-impact-more]');if(more)more.onclick=()=>{area.querySelector('[data-impact-records]').insertAdjacentHTML('beforeend',impact.records.slice(impactOffset,impactOffset+50).map(x=>'<p>'+esc(x.type)+' · <button data-open-org="'+x.id+'" data-record-type="'+x.type+'">'+esc(x.name)+'</button></p>').join(''));impactOffset+=50;more.hidden=impactOffset>=impact.records.length;};area.querySelector('[data-swap-main]').onclick=()=>run(()=>compare(b+':'+a));area.querySelector('[data-merge]').disabled=impact.publicConflict;area.querySelector('[data-merge]').onclick=()=>run(async()=>{if(!confirm('Объединить эти организации и перевести связанные записи на первую?'))return;const fields=Object.fromEntries([...area.querySelectorAll('[data-merge-field]')].map(el=>[el.dataset.mergeField,el.value]));const result=await mutate('wb_merge',{keep:a,other:b,keepRevision:left.revision,otherRevision:right.revision,fields});status('Организации объединены. Предыдущая история сохранена.');showOperation(result.operationId);await refreshLookups();});pairControls(area,'organizations',a,b,left,right);area.scrollIntoView({block:'start',behavior:'smooth'});}
 async function comparePeople(a,b){const r=await api({action:'wb_pair_details',type:'contacts',left:a,right:b}),area=body.querySelector('[data-compare]'),[left,right]=[r.left,r.right];area.innerHTML='<section class="panel"><h2>Сравнение людей</h2><div class="wb-compare">'+[left,right].map(x=>'<div><h3>'+esc(x.name)+'</h3><p>'+esc(x.city||'Город не указан')+'</p><p>'+esc((x.emails||[]).join(' · '))+'</p><p>'+esc((x.phones||[]).join(' · '))+'</p><p>'+esc(x.notes)+'</p><button data-open-org="'+x.id+'" data-record-type="contacts">Открыть человека</button></div>').join('')+'</div><p>Главной останется первая карточка. Каналы и связи объединятся. Предыдущие заметки и письма сохраняются в архивной карточке.</p><div class="actions"><button data-person-swap>Сделать вторую главной</button><button data-person-different>Разные люди</button><button data-person-later>Вернуться позже</button><button data-person-merge>Объединить людей</button></div><div data-operation></div></section>';area.querySelector('[data-person-swap]').onclick=()=>run(()=>comparePeople(b,a));for(const[key,decision]of [['different','different'],['later','later']])area.querySelector('[data-person-'+key+']').onclick=()=>run(async()=>{await api({action:'wb_quality_decide',type:'contacts',left:a,right:b,leftRevision:left.revision,rightRevision:right.revision,decision});pairs=pairs.filter(p=>![a+':'+b,b+':'+a].includes(p.left+':'+p.right));area.innerHTML='';renderScan();status(decision==='different'?'Решение сохранено для команды.':'Пара отложена на 7 дней.');});area.querySelector('[data-person-merge]').onclick=()=>run(async()=>{if(!await AelitaConfirmMail({title:'Проверка объединения людей',facts:[['Основная карточка',left.name],['Архивная карточка',right.name],['Почтовых адресов после',new Set([...(left.emails||[]),...(right.emails||[])]).size],['Телефонов после',new Set([...(left.phones||[]),...(right.phones||[])]).size]],warnings:['Письма и заметки останутся в истории исходных карточек. Новые связи будут переведены на основную. При превышении лимита контактов объединение остановится.'],check:'Я проверил, что это один человек',label:'Объединить людей'}))return;const result=await mutate('wb_merge_people',{keep:a,other:b,keepRevision:left.revision,otherRevision:right.revision});showOperation(result.operationId);await refreshLookups();status('Люди объединены. Прежняя история сохранена.');});pairControls(area,'contacts',a,b,left,right);}

 function renderHelper(){body.innerHTML='<section class="panel"><h2>Найти подборку организаций</h2><label>Что найти<input class="ym-disable-keys" data-query maxlength="300" placeholder="Театры Москвы, которым ещё не писали"></label><button data-query-run>Показать условия и результат</button><div data-query-result></div></section><section class="panel"><h2>Разобрать рабочую заметку</h2><label>Текст<textarea class="ym-disable-keys" data-note-source rows="5" maxlength="4000"></textarea></label><button data-note-parse>Предложить контакты и задачу</button><div data-note-result></div></section>';mountSourceReview();}
 function mountSourceReview(){sourceItems=[];reviewRecord=null;body.insertAdjacentHTML('beforeend','<section class="panel"><h2>Разобрать записи отношений</h2><p class="hint">Выберите карточку и нужные фрагменты. Помощник предложит группировку договорённостей, вопросов и следующих действий с цитатами источников.</p><label>Тип карточки<select data-review-type><option value="organizations">Организация</option><option value="contacts">Человек</option><option value="projects">Проект</option><option value="deals">Сделка / показ</option></select></label><label>Найти карточку<input class="ym-disable-keys" data-review-search placeholder="Начните вводить название"></label><div data-review-records></div><div data-review-sources></div><div data-review-result></div></section>');api({action:'lookups'}).then(r=>{if(active()){reviewLookups=r;renderSourceRecords();}}).catch(e=>status(e.message));}
 function renderSourceRecords(){if(!reviewLookups||!body.querySelector('[data-review-records]'))return;const type=body.querySelector('[data-review-type]').value,q=body.querySelector('[data-review-search]').value.trim().toLowerCase();body.querySelector('[data-review-records]').innerHTML=(reviewLookups[type]||[]).filter(x=>!x.archived&&(!q||x.label.toLowerCase().includes(q))).slice(0,20).map(x=>'<button data-review-record="'+x.id+'" data-review-record-type="'+type+'">'+esc(x.label)+'</button>').join('')||'<p>Карточки не найдены.</p>';}
 async function reviewSources(type,id){const r=await api({action:'record_sources',type,id});if(!active())return;reviewRecord=r.record;sourceItems=r.items;body.querySelector('[data-review-sources]').innerHTML='<h3>'+esc(r.record.name)+'</h3><p>'+esc(r.notice)+'</p>'+r.items.map(x=>'<article class="wb-import-row"><label class="check"><input type="checkbox" data-review-source="'+x.id+'"> '+esc(x.label)+'</label><p>'+esc(x.text)+'</p><a href="'+esc(x.url)+'" target="_blank" rel="noopener">Открыть источник</a></article>').join('')+'<button data-review-run>Предложить разбор выбранного</button>';body.querySelector('[data-review-result]').innerHTML='';}
 async function aiCall(data){const token=window.AelitaStaffSession?.read()?.adminToken;if(!token)throw Error('Для помощника нужен персональный доступ в админку. Выбранные фрагменты остаются здесь.');const response=await fetch('https://api.aelita-production.ru/admin/inbox',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(data),cache:'no-store'}),r=await response.json();if(!response.ok)throw Error(({pilot_disabled:'Помощник сейчас выключен. Выбранные фрагменты сохранены на этом экране.',key_not_configured:'Помощник не настроен. Можно продолжить вручную.',daily_limit:'Лимит помощника на сегодня исчерпан.',provider_invalid_response:'Ответ не прошёл проверку источников. Записи не изменены.'})[r.error]||r.message||'Помощник недоступен. Попробуйте позже.');return r;}
 async function reviewWithAi(){const ids=new Set([...body.querySelectorAll('[data-review-source]:checked')].map(x=>x.dataset.reviewSource)),sources=sourceItems.filter(x=>ids.has(x.id)).map(x=>({id:x.id,text:x.text}));if(!sources.length||sources.length>12)throw Error('Выберите от1 до12 фрагментов.');const text=JSON.stringify({sources});if(text.length>6000)throw Error('Для одного разбора выберите меньше фрагментов, до6000 символов.');let r=await aiCall({action:'ai_ask',kind:'crm_review',text,context:{type:reviewRecord.type,id:reviewRecord.id},includeContacts:true,requestId:rid()});for(let n=0;n<40;n++){if(!active()||stopped)return;if(r.job.status==='done'){renderSourceResult(r.job.result);return;}if(['error','canceled'].includes(r.job.status))throw Error('Разбор не завершён. Исходные записи не менялись.');status('Помощник разбирает только выбранные фрагменты…');await new Promise(resolve=>setTimeout(resolve,1500));r=await aiCall({action:'ai_poll',id:r.job.id});}throw Error('Ожидание истекло. Проверьте незавершённое задание помощника.');}
 function renderSourceResult(result){const labels={summary:'Договорённость / важное',task:'Предложение следующего действия',conflict:'Нужно проверить противоречие',classification:'Основание для уточнения карточки',dedupe:'Признак совпадения'};body.querySelector('[data-review-result]').innerHTML='<h3>Предложенный разбор</h3><p>'+esc(result.text)+'</p>'+(result.items||[]).map((x,index)=>'<article class="wb-import-row"><h4>'+esc(labels[x.kind]||'Проверьте фрагмент')+'</h4>'+x.evidence.map(e=>{const s=sourceItems.find(x=>x.id===e.sourceId);return'<blockquote>'+esc(e.quote)+'</blockquote>'+(s?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.label)+'</a>':'');}).join('')+(x.kind==='task'?'<button data-source-task="'+index+'">Подготовить задачу с этими источниками</button>':'')+'</article>').join('');sourceResult=result;}

 async function query(offset=0){const r=await api({action:'wb_query',query:body.querySelector('[data-query]').value,offset});body.querySelector('[data-query-result]').innerHTML=(r.needsClarification?'<p class="error">'+esc(r.message)+'</p>':'')+'<h3>Условия</h3><ul>'+r.conditions.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'+r.items.map(x=>'<p><button data-open-org="'+x.id+'" data-record-type="'+(x.type||'organizations')+'">'+esc(x.name)+'</button> · '+esc(x.city)+'</p>').join('')+'<p class="hint">Проверено '+r.scanned+' из '+r.totalCandidates+' подходящих карточек. Письма вне CRM и незафиксированные звонки здесь не учитываются.</p>'+(r.next!==null?'<button data-query-next="'+r.next+'">Проверить следующие</button>':'');}
 async function parseNote(){const text=body.querySelector('[data-note-source]').value,r=await api({action:'wb_note_parse',text}),lookups=await api({action:'lookups'});const area=body.querySelector('[data-note-result]');area.innerHTML='<h3>Найденные сведения</h3><dl><dt>Почта</dt><dd>'+esc(r.emails.join(', ')||'Не найдена')+'</dd><dt>Телефоны</dt><dd>'+esc(r.phones.join(', ')||'Не найдены')+'</dd></dl><p class="hint">'+esc(r.warnings.join(' '))+'</p><form><label>Задача<input class="ym-disable-keys" name="title" maxlength="180" required value="'+esc(r.task.title)+'"></label><label>Организация<select name="organizationId"><option value="">Без организации</option>'+lookups.organizations.filter(x=>!x.archived).map(x=>'<option value="'+x.id+'">'+esc(x.label)+'</option>').join('')+'</select></label><label>Срок · Москва<input class="ym-disable-keys" type="datetime-local" name="due" value="'+(r.task.dueAt?new Date(Date.parse(r.task.dueAt)+3*3600000).toISOString().slice(0,16):'')+'"></label><button type="submit">Создать задачу из этой заметки</button></form><div data-operation></div>';area.querySelector('form').onsubmit=event=>{event.preventDefault();run(async()=>{const fields=new FormData(event.currentTarget),due=fields.get('due'),result=await mutate('wb_note_task',{text,data:{title:fields.get('title'),organizationId:fields.get('organizationId'),description:text,dueAt:due?new Date(due+':00+03:00').toISOString():null}});status('Задача создана. Контакты не переносились без выбора человека.');showOperation(result.operationId);});};}
 async function history(){const r=await api({action:'wb_operations'});body.innerHTML='<section class="panel"><h2>Массовые изменения</h2>'+r.items.map(x=>'<article><h3>'+esc(x.kind)+'</h3><p>'+esc(new Date(x.createdAt).toLocaleString('ru-RU'))+' · записей '+x.rows+'</p>'+(x.undone?'<p>Отменено</p>':'<button data-undo="'+x.id+'">Отменить</button>')+'</article>').join('')+(!r.items.length?'<p>Изменений пока нет.</p>':'')+'</section>';}
 async function ai(text){await aiCall({action:'ai_capabilities'});if(text.length<2||text.length>6000)throw Error('Для одного разбора ИИ выберите фрагмент от 2 до 6000 символов.');const token=window.AelitaStaffSession?.read()?.adminToken;if(!token)throw Error('Для ИИ нужен персональный доступ в админку. Обычный разбор текста доступен без ИИ.');const call=async data=>{const response=await fetch('https://api.aelita-production.ru/admin/inbox',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(data),cache:'no-store'}),r=await response.json();if(!response.ok)throw Error(({pilot_disabled:'ИИ-пилот выключен в настройках.',key_not_configured:'Серверный ключ ИИ не настроен.',daily_limit:'Лимит ИИ на сегодня исчерпан.',provider_invalid_response:'ИИ предложил непроверяемые данные. Используйте обычный разбор.'})[r.error]||'ИИ недоступен: '+r.error);return r;};const request=rid();let r=await call({action:'ai_ask',kind:'organization_extract',text,includeContacts:true,requestId:request});for(let i=0;i<40;i++){if(!active()||stopped){if(r.job.status==='queued')await call({action:'ai_cancel',id:r.job.id});return;}if(r.job.status==='done'){await upload(r.job.result.items);return;}if(r.job.status==='error')throw Error('ИИ не завершил разбор: '+r.job.error);status('ИИ разбирает фрагмент…');await new Promise(resolve=>setTimeout(resolve,1500));r=await call({action:'ai_poll',id:r.job.id});}throw Error('Ожидание ИИ истекло. Обычный разбор текста остаётся доступен.');}
 async function run(fn){if(busy)return;busy=true;host.setAttribute('aria-busy','true');try{await fn();}catch(e){status(e.message);}finally{busy=false;host.removeAttribute('aria-busy');}}
 host.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const d=b.dataset;if(d.mode){if(busy){stopped=true;status('Дождитесь остановки текущей операции.');return;}sourceDraft=body.querySelector('[data-source]')?.value||sourceDraft;mode=d.mode;host.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(mode==='import')renderImport();else if(mode==='quality')renderQuality();else if(mode==='helper')renderHelper();else if(mode==='jobs')run(jobs);else run(history);return;}if('planPause'in d){stopped=true;status('Пауза после текущей порции.');if(!busy&&plan?.status==='running')run(async()=>{plan=(await api({action:'wb_plan_control',planId:plan.id,control:'pause'})).plan;renderPlan();});return;}if('scanStop'in d){stopped=true;status('Проверка приостановлена. Показаны частичные результаты.');return;}
  run(async()=>{if(d.importStep){setImportStep(Number(d.importStep));return;}if(d.segmentJob){if(openSegment)await openSegment(d.segmentId,d.segmentJob);return;}if('parse'in d){sourceDraft=body.querySelector('[data-source]').value;await upload(window.AelitaOrganizationParser.text(sourceDraft));}if('ai'in d){const text=body.querySelector('[data-source]'),selected=text.selectionEnd>text.selectionStart?text.value.slice(text.selectionStart,text.selectionEnd):text.value;await ai(selected);}if('resume'in d){job=memory.get('import');offset=0;await review();}if('mapApply'in d){const map=Object.fromEntries([...body.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,Number(el.value)]));source.mapping=map;await upload(window.AelitaOrganizationParser.table(source.rows,map,source.headerRow||0).items.map(x=>({...x,source:(source.sheetName?'Лист '+source.sheetName+' · ':'')+x.source})));}if('editRow'in d)editRow(Number(d.editRow));if('apply'in d)await apply();if('diffRow'in d)await showDiff(Number(d.diffRow));if('selectKind'in d)await selectCategory();if('report'in d)await report();if('shareImport'in d)await shareImport();if('planRun'in d)await runPlan();if('planResume'in d){plan=(await api({action:'wb_plan_control',planId:plan.id,control:'resume'})).plan;await runPlan();}if('planClose'in d){plan=(await api({action:'wb_plan_control',planId:plan.id,control:plan.status==='done'?'close':'cancel'})).plan;await review();}if(d.aiJob){const r=await aiCall({action:'ai_job_get',id:d.aiJob});if(r.job.status==='queued'||r.job.status==='running'){await aiCall({action:'ai_poll',id:d.aiJob});await jobs();}else if(r.job.result){if(r.job.kind==='crm_review'&&r.job.context){renderHelper();await reviewSources(r.job.context.type,r.job.context.id);renderSourceResult(r.job.result);}else{const p=document.createElement('p');p.textContent=r.job.result.text||'Результат готов';body.querySelector('[data-ai-jobs]').append(p);}}}if(d.jobOpen){if(d.jobKind==='import'){job={id:d.jobOpen};renderImport();await review();}else{plan=(await api({action:'wb_plan_status',planId:d.jobOpen})).plan;renderImport();job={id:plan.batchId};await review();renderPlan();}}if('templateSave'in d||'templateLoad'in d){const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(source.rows[source.headerRow||0]))))].map(x=>x.toString(16).padStart(2,'0')).join('');if('templateSave'in d){const name=body.querySelector('[data-template-name]').value.trim();if(!name)throw Error('Назовите шаблон колонок.');memory.set('mapping:'+hash,{name,map:Object.fromEntries([...body.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,Number(el.value)]))});status('Шаблон сохранён для этих заголовков.');}else{const saved=memory.get('mapping:'+hash);if(!saved)throw Error('Для этих заголовков шаблона нет.');source.mapping=saved.map;mapping();status('Шаблон «'+saved.name+'» восстановлен.');}}if('selectPage'in d){for(const el of body.querySelectorAll('[data-import-row]')){const c=el.querySelector('[data-selected]');if(c.disabled)continue;c.checked=true;await preserveChoice(Number(el.dataset.importRow),readChoice(el));}await review();}if('next'in d&&next!==null){offset=next;await review();}if('prev'in d){offset=Math.max(0,offset-50);await review();}if('scan'in d)await scan();if('group'in d){groupFilter=d.group;pairPage=0;renderScan();}if('pairPage'in d){pairPage=Math.max(0,Number(d.pairPage));renderScan();}if('issuePage'in d){issuePage=Math.max(0,Number(d.issuePage));renderScan();}if('queryRun'in d)await query();if('queryNext'in d)await query(Number(d.queryNext));if('noteParse'in d)await parseNote();if(d.reviewRecord)await reviewSources(d.reviewRecordType,d.reviewRecord);if('reviewRun'in d)await reviewWithAi();if('sourceTask'in d){const item=sourceResult.items[Number(d.sourceTask)],text=item.evidence.map(e=>e.quote+'\nИсточник: '+sourceItems.find(x=>x.id===e.sourceId)?.url).join('\n\n');body.querySelector('[data-note-source]').value=text;await parseNote();const org=body.querySelector('[data-note-result] [name=organizationId]');if(org&&reviewRecord.type==='organizations')org.value=reviewRecord.id;body.querySelector('[data-note-result]').scrollIntoView({block:'start'});}if(d.compare)await compare(d.compare);if(d.different){const p=pairs.find(x=>x.left+':'+x.right===d.different);await api({action:'wb_quality_decide',type:p.type||'organizations',left:p.left,right:p.right,leftRevision:p.leftRevision,rightRevision:p.rightRevision,decision:'different'});pairs=pairs.filter(x=>x!==p);pairPage=0;renderScan();}if(d.openOrg)await openRecord(d.recordType||'organizations',d.openOrg);if(d.undo&&confirm('Отменить операцию? Если после неё данные менялись, отмена будет остановлена.')){await mutate('wb_undo',{id:d.undo});status('Операция отменена.');await refreshLookups();if(mode==='history')await history();}});
 });
 body.addEventListener('input',event=>{if(event.target.matches('[data-source]'))sourceDraft=event.target.value;if(event.target.matches('[data-review-search]'))renderSourceRecords();});
 body.addEventListener('change',event=>{if(event.target.matches('[data-issue-filter]')){issueFilter=event.target.value;issuePage=0;renderScan();return;}if(event.target.matches('[data-review-type]')){reviewRecord=null;sourceItems=[];body.querySelector('[data-review-sources]').innerHTML='';body.querySelector('[data-review-result]').innerHTML='';renderSourceRecords();return;}if(event.target.matches('[data-selected],[data-decision]')){const row=event.target.closest('[data-import-row]');preserveChoice(Number(row.dataset.importRow),readChoice(row));return;}if(event.target.matches('[data-review-filter]')){reviewFilter=event.target.value;offset=0;run(review);return;}if(event.target.matches('[data-map]')){const map=Object.fromEntries([...body.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,Number(el.value)]));source.mapping=map;const sample=body.querySelector('[data-column-samples="'+event.target.dataset.map+'"]');sample.textContent=source.rows.slice((source.headerRow||0)+1,(source.headerRow||0)+4).map(row=>row[Number(event.target.value)]||'—').join(' / ');return;}if(event.target.matches('[data-header]')&&source?.kind==='table'){const row=Number(event.target.value)-1;if(!Number.isInteger(row)||row<0||row>=source.rows.length)return;source.headerRow=row;delete source.mapping;mapping();return;}const file=event.target.matches('[data-file]')?event.target.files[0]:event.target.matches('[data-encoding]')?source?.file:null;if(file)run(async()=>{source={...(await window.AelitaReadOrganizationFile(file,{encoding:body.querySelector('[data-encoding]').value})),name:file.name,file};if(source.sheets){body.querySelector('[data-sheets]').innerHTML='<label>Лист<select data-sheet>'+source.sheets.map((s,i)=>'<option value="'+i+'">'+esc(s)+'</option>').join('')+'</select></label>';}if(source.kind==='table'){mapping();setImportStep(2);status('Проверьте колонки файла.');}else{body.querySelector('[data-source]').value=source.text;status('Текст извлечён. Проверьте его и выберите способ разбора.');}});if(event.target.matches('[data-sheet]')&&source?.file)run(async()=>{const file=source.file;source={...(await window.AelitaReadOrganizationFile(file,{sheet:Number(event.target.value)})),file,name:file.name};mapping();});});
 renderImport();if(!resumeJob&&job?.status==='ready')run(review);if(resumeJob){run(async()=>{if(resumeJob.kind==='plan'){plan=(await api({action:'wb_plan_status',planId:resumeJob.id})).plan;job={id:plan.batchId};}else job={id:resumeJob.id};await review();if(plan)renderPlan();});}return {stop:()=>{stopped=true;}};
};
